'use client'

import * as React from 'react'
import { Menu } from 'lucide-react'

import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

import type { NavigationAction, NavigationBrand, NavigationItem } from './types'

export interface MobileDrawerProps {
  brand: NavigationBrand
  items: readonly NavigationItem[]
  actions?: readonly NavigationAction[]
  trigger?: React.ReactNode
  triggerLabel?: string
  navigationLabel?: string
  className?: string
}

function ExternalAttributes({ external }: { external?: boolean }) {
  return external ? { target: '_blank', rel: 'noopener noreferrer' } : {}
}

export function MobileDrawer({
  brand,
  items,
  actions = [],
  trigger,
  triggerLabel = 'Abrir menu',
  navigationLabel = 'Navegação móvel',
  className,
}: MobileDrawerProps) {
  return (
    <Dialog>
      <DialogTrigger asChild>
        {trigger ?? (
          <Button variant="ghost" size="icon" aria-label={triggerLabel}>
            <Menu className="h-5 w-5" aria-hidden="true" />
          </Button>
        )}
      </DialogTrigger>
      <DialogContent
        className={cn(
          'bottom-0 left-auto right-0 top-0 flex h-dvh w-[min(24rem,90vw)] max-w-none translate-x-0 translate-y-0 flex-col rounded-none p-0 data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right',
          className,
        )}
      >
        <div className="border-b px-6 py-5 pr-14">
          <DialogTitle className="text-left">
            <a href={brand.href ?? '/'} className="inline-flex items-center gap-3">
              {brand.logo}
              <span>{brand.label}</span>
            </a>
          </DialogTitle>
          <DialogDescription className="sr-only">{navigationLabel}</DialogDescription>
        </div>

        <nav className="flex-1 overflow-y-auto px-4 py-5" aria-label={navigationLabel}>
          <ul className="space-y-1">
            {items.map((item) => (
              <li key={item.href}>
                <DialogClose asChild>
                  <a
                    href={item.href}
                    aria-current={item.current ? 'page' : undefined}
                    className={cn(
                      'flex min-h-11 items-center gap-3 rounded-md px-3 py-2 text-sm font-medium transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      item.current && 'bg-muted text-primary',
                    )}
                    {...ExternalAttributes(item)}
                  >
                    {item.icon}
                    {item.label}
                  </a>
                </DialogClose>
                {item.children?.length ? (
                  <ul className="mb-2 ml-5 border-l pl-3">
                    {item.children.map((child) => (
                      <li key={child.href}>
                        <DialogClose asChild>
                          <a
                            href={child.href}
                            aria-current={child.current ? 'page' : undefined}
                            className="block rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                            {...ExternalAttributes(child)}
                          >
                            {child.label}
                          </a>
                        </DialogClose>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ul>
        </nav>

        {actions.length ? (
          <div className="grid gap-2 border-t p-4">
            {actions.map((action) => (
              <Button key={action.href} asChild variant={action.variant}>
                <a href={action.href} {...ExternalAttributes(action)}>
                  {action.label}
                </a>
              </Button>
            ))}
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

import * as React from 'react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

import { MobileDrawer } from './MobileDrawer'
import type { NavigationAction, NavigationBrand, NavigationItem } from './types'

export interface NavbarCenteredProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  brand: NavigationBrand
  items: readonly NavigationItem[]
  actions?: readonly NavigationAction[]
  navigationLabel?: string
  sticky?: boolean
}

export function NavbarCentered({
  brand,
  items,
  actions = [],
  navigationLabel = 'Navegação principal',
  sticky = false,
  className,
  ...props
}: NavbarCenteredProps) {
  return (
    <header
      className={cn(
        'z-40 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80',
        sticky && 'sticky top-0',
        className,
      )}
      {...props}
    >
      <div className="mx-auto grid h-20 max-w-7xl grid-cols-[1fr_auto_1fr] items-center px-4 sm:px-6 lg:px-8">
        <nav className="hidden justify-self-start lg:block" aria-label={navigationLabel}>
          <ul className="flex items-center gap-1">
            {items.slice(0, Math.ceil(items.length / 2)).map((item) => (
              <li key={item.href}>
                <a
                  href={item.href}
                  aria-current={item.current ? 'page' : undefined}
                  target={item.external ? '_blank' : undefined}
                  rel={item.external ? 'noopener noreferrer' : undefined}
                  className={cn(
                    'block rounded-md px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                    item.current && 'text-primary',
                  )}
                >
                  {item.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>

        <a
          href={brand.href ?? '/'}
          className="col-start-2 inline-flex items-center gap-3 rounded-sm text-center font-semibold tracking-tight focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {brand.logo}
          <span>{brand.label}</span>
        </a>

        <div className="hidden items-center justify-self-end lg:flex">
          <nav aria-label={`${navigationLabel} — continuação`}>
            <ul className="flex items-center gap-1">
              {items.slice(Math.ceil(items.length / 2)).map((item) => (
                <li key={item.href}>
                  <a
                    href={item.href}
                    aria-current={item.current ? 'page' : undefined}
                    target={item.external ? '_blank' : undefined}
                    rel={item.external ? 'noopener noreferrer' : undefined}
                    className={cn(
                      'block rounded-md px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      item.current && 'text-primary',
                    )}
                  >
                    {item.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
          {actions[0] ? (
            <Button asChild variant={actions[0].variant} size="sm" className="ml-3">
              <a
                href={actions[0].href}
                target={actions[0].external ? '_blank' : undefined}
                rel={actions[0].external ? 'noopener noreferrer' : undefined}
              >
                {actions[0].label}
              </a>
            </Button>
          ) : null}
        </div>

        <div className="col-start-3 row-start-1 justify-self-end lg:hidden">
          <MobileDrawer
            brand={brand}
            items={items}
            actions={actions}
            navigationLabel={navigationLabel}
          />
        </div>
      </div>
    </header>
  )
}

import type * as React from 'react'

export interface NavigationLink {
  label: React.ReactNode
  href: string
  description?: string
  icon?: React.ReactNode
  external?: boolean
  current?: boolean
}

export interface NavigationItem extends NavigationLink {
  children?: readonly NavigationLink[]
}

export interface NavigationAction extends NavigationLink {
  variant?: 'default' | 'secondary' | 'outline' | 'ghost' | 'link'
}

export interface NavigationBrand {
  label: string
  href?: string
  logo?: React.ReactNode
}

export interface FooterColumn {
  title: string
  links: readonly NavigationLink[]
}

export interface SocialLink {
  label: string
  href: string
  icon: React.ReactNode
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
